package com.wormzjl.icheme.runtime.instrument;

import com.wormzjl.icheme.registry.ModItems;
import com.wormzjl.icheme.registry.ModDataComponents;
import com.wormzjl.icheme.runtime.fluid.*;
import com.wormzjl.icheme.network.InstrumentNetwork;
import com.wormzjl.icheme.world.item.*;
import com.wormzjl.icheme.world.level.block.FluidDeviceBlock;
import net.minecraft.core.*;
import net.minecraft.resources.*;
import net.minecraft.server.MinecraftServer;
import net.minecraft.server.level.*;
import net.minecraft.world.InteractionHand;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.level.Level;
import net.minecraft.world.level.block.Block;
import net.minecraft.world.level.saveddata.SavedData;
import java.util.*;

/** Server-thread attachment authority. Transactions transfer items only when their scheduled event commits. */
public final class InstrumentService {
    private final MinecraftServer server;
    private final FluidWorldAuthority world;
    private final AccessoryStore store;
    private final Map<UUID,ItemStack> exactStacks=new HashMap<>();
    private final Map<UUID,Set<InstrumentNetwork.Target>> watchers=new HashMap<>();
    private final Map<UUID,Instrument.Sample> samples=new HashMap<>();

    public InstrumentService(MinecraftServer server,FluidWorldAuthority world){this.server=server;this.world=world;store=server.overworld().getDataStorage().computeIfAbsent(new SavedData.Factory<>(AccessoryStore::new,AccessoryStore::load),"icheme_accessories");}
    public boolean occupied(long host){return !store.host(host).isEmpty()||store.pending().stream().anyMatch(p->p.key().host()==host&&p.install());}
    public boolean observes(long host){return watchers.values().stream().anyMatch(set->set.stream().anyMatch(t->t.key().host()==host));}
    public void request(ServerPlayer player,InteractionHand hand,boolean remove){if(player.isSpectator()||!player.mayBuild())return;var held=player.getItemInHand(hand);GaugeSettings.Kind kind=held.getItem() instanceof GaugeItem g?g.kind():null;if(!remove&&kind==null||remove&&!held.is(ModItems.ACCESSORY_WRENCH.get()))return;double reach=player.blockInteractionRange();var hosts=InstrumentHosts.nearby(player.level(),player.getEyePosition(),8);var selected=InstrumentHosts.select(hosts,player.getEyePosition(),player.getLookAngle(),reach,kind,remove);
        InstrumentHosts.Host host;String mount;UUID instance;AccessoryStore.Type type;GaugeSettings settings=null;
        if(selected!=null){host=selected.host();mount=selected.mount().id();if(remove){var installed=store.get(new Instrument.Key(host.identity(),mount));if(installed==null)return;instance=installed.instance();type=installed.settings().kind()==GaugeSettings.Kind.PRESSURE?AccessoryStore.Type.PRESSURE:AccessoryStore.Type.TEMPERATURE;}else{if(host.occupied(selected.mount())||!InstrumentHosts.clear(player.level(),host,selected.mount())||host.pipe()&&occupied(host.identity()))return;settings=held.get(ModDataComponents.GAUGE_SETTINGS.get());if(settings==null||settings.kind()!=kind)return;instance=UUID.randomUUID();type=kind==GaugeSettings.Kind.PRESSURE?AccessoryStore.Type.PRESSURE:AccessoryStore.Type.TEMPERATURE;}}
        else if(remove){host=null;PipeAccessoryMount selectedLegacy=null;double nearest=reach;for(var candidate:hosts){if(!(candidate.entity() instanceof com.wormzjl.icheme.world.level.block.entity.FluidDeviceBlockEntity pipe))continue;var legacy=PipeAccessoryMount.of(pipe);if(legacy==null)continue;var hit=legacy.bounds().clip(player.getEyePosition(),player.getEyePosition().add(player.getLookAngle().scale(reach)));if(hit.isPresent()&&hit.get().distanceTo(player.getEyePosition())<=nearest&&InstrumentHosts.reachable(player,candidate,legacy)){host=candidate;selectedLegacy=legacy;nearest=hit.get().distanceTo(player.getEyePosition());}}if(host==null)return;type=InstrumentHosts.legacy(host.entity().getBlockState());mount=selectedLegacy.id();var fitting=store.legacy(host.identity());if(fitting==null)return;instance=fitting.instance();}
        else return;
        if(!permission(player,host,held))return;var p=new AccessoryStore.Pending(UUID.randomUUID(),player.getUUID(),new Instrument.Key(host.identity(),mount),instance,store.revision(host.identity()),!remove,type,settings,player.level().dimension().location().toString(),host.entity().getBlockPos().asLong(),player.getInventory().selected,hand==InteractionHand.OFF_HAND);if(store.queue(p))exactStacks.put(p.request(),held);
    }
    private static boolean permission(ServerPlayer player,InstrumentHosts.Host host,ItemStack held){var pos=host.entity().getBlockPos();return player.mayBuild()&&!player.isSpectator()&&player.serverLevel().mayInteract(player,pos)&&player.mayUseItemAt(pos,Direction.UP,held);}
    public void tick(long tick){if(store.nextDue()==0)store.nextDue(tick+100);if(tick<store.nextDue())return;store.nextDue(tick+100);for(var p:store.pending()){var player=server.getPlayerList().getPlayer(p.player());if(player==null)continue;var level=level(p.dimension());if(level==null||!level.hasChunkAt(BlockPos.of(p.position())))continue;commit(player,level,p);store.finish(p.request());exactStacks.remove(p.request());}for(var i:store.installed()){var h=world.instrumentHost(i.key().host());if(h==null)continue;var m=h.mount(i.key().mount());if(m==null||!m.kinds().contains(i.settings().kind())||h.pipe()&&InstrumentHosts.legacy(h.entity().getBlockState())!=null){var removed=store.remove(i.key(),i.instance());if(removed!=null){refund(null,h.entity().getLevel(),h.entity().getBlockPos(),item(removed));samples.remove(i.instance());sync(h);}}}prune();}
    private void commit(ServerPlayer player,ServerLevel level,AccessoryStore.Pending p){var host=InstrumentHosts.at(level,BlockPos.of(p.position()));if(host==null||host.identity()!=p.key().host()||player.serverLevel()!=level||store.revision(host.identity())!=p.expectedRevision())return;var hand=p.offhand()?InteractionHand.OFF_HAND:InteractionHand.MAIN_HAND;var held=player.getItemInHand(hand);if(!permission(player,host,held))return;if(!p.offhand()&&player.getInventory().selected!=p.slot()||exactStacks.containsKey(p.request())&&held!=exactStacks.get(p.request()))return;var mount=host.mount(p.key().mount());if(p.install()){if((!(held.getItem() instanceof GaugeItem gauge)||gauge.kind()!=p.settings().kind())||!p.settings().equals(held.get(ModDataComponents.GAUGE_SETTINGS.get()))||mount==null||host.occupied(mount)||!InstrumentHosts.clear(level,host,mount)||!mount.kinds().contains(p.settings().kind())||host.pipe()&&!store.host(host.identity()).isEmpty()||!InstrumentHosts.reachable(player,host,mount))return;if(store.install(p)==null)return;if(!player.isCreative())held.shrink(1);}
        else {if(!held.is(ModItems.ACCESSORY_WRENCH.get()))return;if(p.type()==AccessoryStore.Type.PRESSURE||p.type()==AccessoryStore.Type.TEMPERATURE){if(mount==null||!InstrumentHosts.reachable(player,host,mount))return;var removed=store.remove(p.key(),p.instance());if(removed==null)return;refund(player,level,host.entity().getBlockPos(),item(removed));samples.remove(removed.instance());}else{if(InstrumentHosts.legacy(host.entity().getBlockState())!=p.type()||!(host.entity() instanceof com.wormzjl.icheme.world.level.block.entity.FluidDeviceBlockEntity pipe)||PipeAccessoryMount.of(pipe)==null||!InstrumentHosts.reachable(player,host,PipeAccessoryMount.of(pipe))||store.legacy(host.identity())==null||!store.legacy(host.identity()).instance().equals(p.instance())||!world.removePipeAccessory(host.identity()))return;var recovered=store.removeLegacy(host.identity(),p.instance());if(recovered==null)return;clearLegacy(host);refund(player,level,host.entity().getBlockPos(),item(recovered.type()));}}
        sync(host);world.markViewDirty(host.identity());player.inventoryMenu.broadcastChanges();
    }
    private ServerLevel level(String name){return server.getLevel(ResourceKey.create(net.minecraft.core.registries.Registries.DIMENSION,ResourceLocation.parse(name)));}
    private void sync(InstrumentHosts.Host host){host.metadata().set(store.host(host.identity()),store.revision(host.identity()));host.entity().setChanged();InstrumentHosts.loaded(host.entity());var l=host.entity().getLevel();var pos=host.entity().getBlockPos();l.sendBlockUpdated(pos,host.entity().getBlockState(),host.entity().getBlockState(),Block.UPDATE_CLIENTS);}
    public void bind(InstrumentHosts.Host host){if(host!=null&&(!host.metadata().installed().equals(store.host(host.identity()))||host.metadata().revision()!=store.revision(host.identity())))sync(host);}
    public void recoverHost(long id){var host=world.instrumentHost(id);if(host!=null)recover(id,host.entity().getLevel(),host.entity().getBlockPos(),host.pipe()?InstrumentHosts.legacy(host.entity().getBlockState()):null,host.metadata().recoverOnBreak());}
    public void recover(long id,Level level,BlockPos position,AccessoryStore.Type legacy,boolean drop){for(var i:store.host(id))if(store.remove(i.key(),i.instance())!=null){if(drop)refund(null,level,position,item(i));samples.remove(i.instance());}var fitting=store.legacy(id);if(fitting!=null&&store.removeLegacy(id,fitting.instance())!=null&&drop)refund(null,level,position,item(fitting.type()));forget(id);}
    public void legacyInstalled(long host,AccessoryStore.Type type){store.installLegacy(host,type);bind(world.instrumentHost(host));}
    public void recoverLegacy(long host,Level level,BlockPos position){var old=store.legacy(host);if(old!=null&&store.removeLegacy(host,old.instance())!=null){refund(null,level,position,item(old.type()));bind(world.instrumentHost(host));}}
    private static void clearLegacy(InstrumentHosts.Host host){var e=host.entity();var s=e.getBlockState().setValue(FluidDeviceBlock.SIGHT_GLASS,false).setValue(FluidDeviceBlock.SHUTOFF,FluidDeviceBlock.Shutoff.NONE).setValue(FluidDeviceBlock.PRESSURE_CONTROL,false);s=FluidDeviceBlock.connectedState(s,e.getLevel(),e.getBlockPos());e.getLevel().setBlock(e.getBlockPos(),s,Block.UPDATE_ALL);if(e instanceof com.wormzjl.icheme.world.level.block.entity.FluidDeviceBlockEntity pipe)pipe.refreshGeometry(pipe.bore(),true);}
    public static ItemStack item(Instrument.Installed i){var stack=item(i.settings().kind()==GaugeSettings.Kind.PRESSURE?AccessoryStore.Type.PRESSURE:AccessoryStore.Type.TEMPERATURE);stack.set(ModDataComponents.GAUGE_SETTINGS.get(),i.settings());return stack;}
    public static ItemStack item(AccessoryStore.Type type){return new ItemStack(switch(type){case PRESSURE->ModItems.PRESSURE_GAUGE.get();case TEMPERATURE->ModItems.TEMPERATURE_GAUGE.get();case SIGHT_GLASS->ModItems.PIPELINE_SIGHT_GLASS.get();case SHUTOFF->ModItems.PIPELINE_SHUTOFF_VALVE.get();case CHECK->ModItems.PIPELINE_CHECK_VALVE.get();case PRESSURE_VALVE->ModItems.PRESSURE_CONTROL_VALVE.get();});}
    private static void refund(ServerPlayer player,Level level,BlockPos pos,ItemStack stack){if(player!=null){if(player.getInventory().add(stack))return;player.drop(stack,false);}else Block.popResource(level,pos,stack);}
    public void watch(ServerPlayer player,List<InstrumentNetwork.Target> add,List<InstrumentNetwork.Target> remove){var set=watchers.computeIfAbsent(player.getUUID(),k->new HashSet<>());for(var t:remove){set.remove(t);world.instrumentObservationChanged(t.key().host());}for(var t:add){if(set.size()>=64||!valid(player,t))continue;set.add(t);world.instrumentObservationChanged(t.key().host());var sample=samples.get(t.instance());if(sample!=null)InstrumentNetwork.send(player,t,sample,world.onlineTick());}}
    private boolean valid(ServerPlayer p,InstrumentNetwork.Target t){var i=store.get(t.key());var host=world.instrumentHost(t.key().host());var mount=host==null?null:host.mount(t.key().mount());return i!=null&&i.instance().equals(t.instance())&&host!=null&&host.entity().getLevel()==p.serverLevel()&&host.entity().getBlockPos().equals(t.position())&&mount!=null&&mount.centre().distanceToSqr(p.position())<=128*128;}
    private void prune(){var hosts=new HashSet<Long>();for(var it=watchers.entrySet().iterator();it.hasNext();){var e=it.next();var p=server.getPlayerList().getPlayer(e.getKey());e.getValue().removeIf(t->{boolean remove=p==null||p.hasDisconnected()||!valid(p,t);if(remove)hosts.add(t.key().host());return remove;});if(e.getValue().isEmpty())it.remove();}hosts.forEach(world::instrumentObservationChanged);}
    public void forget(long id){var removed=store.host(id);removed.forEach(i->samples.remove(i.instance()));for(var set:watchers.values())set.removeIf(t->t.key().host()==id);world.instrumentObservationChanged(id);}
    public void publish(long id,FluidView view){var host=world.instrumentHost(id);if(host==null)return;bind(host);for(var i:store.host(id)){var mount=host.mount(i.key().mount());if(mount==null)continue;long tick=view.committedTick();Instrument.Sample sample;
        if(host.pipe()){var reading=world.instrumentPipeReading(id);if(i.settings().kind()==GaugeSettings.Kind.PRESSURE)sample=reading!=null&&Double.isFinite(reading.pressure())?new Instrument.Sample(reading.pressure(),tick,Instrument.Availability.AVAILABLE):Instrument.Sample.unavailable(tick);else sample=Instrument.Sample.temperature(reading!=null&&reading.flowing()&&world.onlineTick()-tick<=100?reading.temperature():null,samples.get(i.instance()),tick);}
        else if(i.settings().kind()==GaugeSettings.Kind.TEMPERATURE)sample=view.state()!=null?new Instrument.Sample(view.state().temperature(),tick,Instrument.Availability.AVAILABLE):Instrument.Sample.unavailable(tick);
        else {Double pressure=view.tank()==null?null:mount.top()?view.tank().topPressure():view.tank().bottomPressure();sample=pressure==null?Instrument.Sample.unavailable(tick):new Instrument.Sample(pressure,tick,Instrument.Availability.AVAILABLE);}
        samples.put(i.instance(),sample);var target=new InstrumentNetwork.Target(host.entity().getBlockPos(),i.key(),i.instance());for(var e:watchers.entrySet())if(e.getValue().contains(target)){var player=server.getPlayerList().getPlayer(e.getKey());if(player!=null&&valid(player,target))InstrumentNetwork.send(player,target,sample,world.onlineTick());}
    }}
}
